"""Public verification for Mission Order QR codes."""

from __future__ import annotations

from django.core import signing
from rest_framework import status
from rest_framework.permissions import AllowAny
from rest_framework.response import Response
from rest_framework.views import APIView

from apps.ops import mission_order_pdf
from apps.ops.models import Mission


class MissionOrderVerifyView(APIView):
    """Confirm that a printed Mission Order was generated by TOWEMS."""

    authentication_classes = []
    permission_classes = [AllowAny]

    def get(self, request, token):
        try:
            payload = mission_order_pdf.load_verification_token(token)
        except signing.BadSignature:
            return Response(
                {
                    "valid": False,
                    "detail": "This QR code is not a valid Mission Order verification code.",
                },
                status=status.HTTP_400_BAD_REQUEST,
            )

        if not isinstance(payload, dict):
            return Response(
                {
                    "valid": False,
                    "detail": "This QR code is not a valid Mission Order verification code.",
                },
                status=status.HTTP_400_BAD_REQUEST,
            )

        mission = Mission.objects.filter(pk=payload.get("mission_id")).first()
        if mission is None or mission.mission_number != payload.get("mission_number"):
            return Response(
                {
                    "valid": False,
                    "detail": "The Mission Order record could not be found.",
                },
                status=status.HTTP_404_NOT_FOUND,
            )

        response = Response(
            {
                "valid": True,
                "generated_by": "Tactical Operations Wings Enterprise Management System",
                "document": "Mission Order",
                "mission_number": mission.mission_number,
                "mission_order_number": payload.get("order_number"),
                "issued_at": payload.get("issued_at"),
            }
        )
        response["Cache-Control"] = "no-store"
        return response

